var profileSideBar=document.querySelector(".profile--sideBar"),faqBox=document.querySelector(".faq__box");if(profileSideBar){const e=document.querySelector(".profile--sideBar"),t=document.querySelector(".user--name"),o=document.querySelector(".profile_cancel");t.addEventListener("click",()=>{e.classList.toggle("active")}),o.addEventListener("click",()=>{e.classList.toggle("active")})}if(faqBox){const e=document.querySelectorAll(".faq__box");e.forEach(e=>{e.addEventListener("click",()=>{e.classList.toggle("active")})})}window.addEventListener("contextmenu",function(e){e.preventDefault()},!1),document.onkeydown=function(e){if(e.ctrlKey&&(67===e.keyCode||85===e.keyCode||83===e.keyCode||73===e.keyCode))return!1};